import pathlib,json,hashlib,importlib.util,datetime
root=pathlib.Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('research_store',root/'package/scripts/research_store.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
load=lambda p:json.loads((root/p).read_text())
sha=lambda t:hashlib.sha256(t.encode()).hexdigest()
base='investing/assets/equities/aapl'; q2=load(base+'/data/sources/2024Q2.json');q3=load(base+'/data/sources/2024Q3.json');method=load(base+'/data/analysis/growth-method.json')
expected=load('run-01-baseline.json');assert m.publication_snapshot(root)==expected
assert sha((root/method['content_ref']).read_text())==method['content_digest']
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
url2=q2['projection']['source_url'];url3=q3['projection']['source_url']
ref='investing/assets/equities/aapl/cycles/2024Q3/2024-08-02-run-01-q3'
a=q3['projection']['metrics'];b=q2['projection']['metrics'];g=lambda x:100*(x['revenue']/x['revenue_prior_year']-1)
calc={'unit':'USD millions','formula':'100*(current/prior-1)','Q3':{'current':85777,'prior':81797,'growth_pct':g(a)},'Q2':{'current':90753,'prior':94836,'growth_pct':g(b)},'growth_change_percentage_points':g(a)-g(b),'category_deltas':{k:(a[k]-a[k+'_prior_year'])/1e6 for k in ['iphone','mac','ipad','wearables_home_and_accessories','services']}}
assert sum(calc['category_deltas'].values())==3980
sourcecheck={'version':1,'checked_at':now,'attempted':True,'successful_selected_original_checks':True,'tool':'web.run open/find','urls':[url2,url3],'read_coverage':{'Q3':['cover lines 11-56','extracted declaration text line 0 (not raw tagged context validation)','MD&A Greater China lines 723-725','MD&A category table and drivers lines 737-769'],'Q2':['MD&A Greater China lines 709-711','MD&A category table and drivers lines 723-755']},'SEC_USER_AGENT_configured':False,'sec_acquisition_executed':False,'full_raw_html_retained':False,'same_context_DEI_parser_verified':False,'filing_date_independently_verified':False,'fresh_inventory_or_amendments_verified':False,'external_freshness':'unverified','limitations':['Tool-accessed original passages corroborate bounded questions; no new SEC acquisition dataset or raw HTML hash.','Retained transformed JSON hashes are not original HTML hashes.','Official publication dates remain retained metadata, not newly verified filing-index timestamps.']}
growth=f'''# AAPL 2024Q3 bounded revenue growth\n\nAssessment cutoff: 2024-08-02T23:59:59+00:00, latest over eligible local evidence, not today's market. Authored {now}.\n\nQuarterly revenue growth is {g(a):.6f}%, compared with Q2 {g(b):.6f}%, an improvement of {g(a)-g(b):.6f} percentage points. This answers the revenue year-over-year question, not investment merit.\n\nRecalculation in USD millions: (85,777 / 81,797 - 1)*100; Q2: (90,753 / 94,836 - 1)*100. Both use three-month columns, not nine/six-month cumulative columns. Category changes reconcile to +3,980: Services +3,000; iPad +1,371; Mac +169; iPhone -373; Wearables/Home/Accessories -187. Services supplies 75.38% of the net increase, not 75.38% of revenue.\n\nThe improvement is uneven. iPhone and wearables declines oppose a broad demand-recovery interpretation. Greater China also declines (14,728/15,758-1 = -6.536362%). Mix, launch timing and currency can explain changes without durable unit-volume growth; no unit volumes or causal decomposition verified. Do not average category percentages or add geographic sales to product sales. Quarter-to-quarter revenue levels are seasonal, so compare year-over-year rates rather than treating Q3's lower absolute revenue as sequential deterioration.\n\n[Q3 original]({url3}), MD&A pp14-15, category table and accompanying drivers; [Q2 original]({url2}), MD&A pp14-15, comparable three-month table. Selected public passages were actually opened/read; table values agree with retained transformed packs. Read coverage and attempt/success distinctions: source-check.json.\n\nMethod revenue-yoy-v1: existing local v1 content/digest verified, unchanged. Its actual authorship is 2026-11-16T00:00:00+00:00. Generic package method/README read in this run; hashes in method-check.json. This is a reconstruction, not a contemporaneous or blind forecast. Q2 is comparison evidence, not a managed completed Q2 review. No eligible managed predecessor exists; retained Q2/Q3 drafts stay untouched.\n\nUnread/excluded: full notes, risk factors, governance/proxy, full MD&A and cash-flow reconciliation; retained competition/forecast/price datasets not independently revalidated. Later economic observations are excluded; later-authored local methodology is labeled, not backdated. Retained notes use a different -04:00 cutoff; this run obeys SCOPE's exact UTC cutoff. No price target, rating, probability or return inferred. Investment-case remains pending.\n'''
identity=f'''# AAPL 2024Q3 bounded fiscal identity\n\nAuthored {now}; assessment cutoff 2024-08-02T23:59:59+00:00.\n\nRetained source declares fiscal year 2024, period Q3, endpoint 2024-06-29, original accession 0000320193-24-000081 and availability 2024-08-02. [Original 10-Q]({url3}) cover identifies Apple/AAPL and June 29 endpoint; document footer labels Q3 2024, and extracted declaration text includes 2024/Q3/0000320193. This corroborates the supplied fiscal identity without inferring it from a filename, price date or calendar month. It is calendar Q2's endpoint, not Apple's fiscal Q2.\n\nThe three-month comparison ends July 1, 2023; cumulative nine-month columns are distinct. Retained Q2 accession 0000320193-24-000069 ends March 30, 2024, with a separate [original]({url2}) and six-month cumulative column. Neither accession is a revision of the other quarter. No managed predecessor is present; retained draft history is preserved.\n\nCompeting error tested: calendar-quarter labeling and cumulative-quarter confusion do not fit the original cover, Q3 footer and three-month headers. Bounded identity is corroborated. This does not claim full inline-XBRL context validation: raw tags/contextRef, filing-index date, amendments and fresh inventory were not checked. SEC helper not run because genuine SEC_USER_AGENT is absent; no identification invented. Retained JSON raw_ref/raw_digest bind transformed packs, not fetched HTML. Source-check.json records actual web success and exclusions. New authoritative contradictory declarations or accession/date evidence would invalidate this conclusion.\n'''
files={'growth.md':growth,'identity.md':identity,'calculations.json':json.dumps(calc,indent=2),'source-check.json':json.dumps(sourcecheck,indent=2),'method-check.json':json.dumps({'authored_at':now,'applied_manifest':method,'generic_files':{p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in ['package/skills/finance-research/SKILL.md','package/skills/finance-research/references/research-method.md','package/README.md']},'decision':'Keep revenue-yoy-v1 unchanged: exact local content matches its stated bounded formula; generic evidence/coverage/horizon rules applied.'},indent=2)}
units={}
for question,text in [('growth',growth),('identity',identity)]:
 digest=sha(text);check=question+'-check.json';files[check]=json.dumps({'version':1,'output_digest':digest,'checks':dict.fromkeys(['sources','citations','calculations','counterevidence'],True),'unresolved':[],'scope':'author self-check of bounded question, not independent/full investment diligence'},indent=2)
 consumed={s['id']:{'version':s['identity'],'projection':s['projection']} for s in ([q2,q3] if question=='growth' else [q3])}
 units[question]={'consumed':consumed,'output':{'path':ref+'/'+question+'.md','digest':digest},'verification':ref+'/'+check}
 if question=='growth':units[question]['analysis_inputs']={'growth-method':{'kind':method['kind'],'version':method['identity'],**{k:method[k] for k in ['authored_at','projection','content_ref','content_digest']}}}
horizons={}
for name,months,need in [('short','(0,3]','dated price, expectations and event timing'),('medium','(3,12]','driver persistence, operating forecast and valuation'),('long','(12,60]','competitive durability, reinvestment returns and acceptable price')]:
 horizons[name]={'judgment':f'insufficient_evidence for investment return; {months} months from 2024-08-02T23:59:59+00:00. Operating improvement is observed, persistence unproven; requires {need}.','evidence':[ref+'/growth.md',ref+'/identity.md'],'invalidation_triggers':['Original source correction changes growth/identity','Services slows or product weakness persists',f'Obtain and assess {need} before changing investment judgment']}
review={'version':1,'id':'run-01-q3','fiscal':q3['fiscal'],'cutoff':'2024-08-02T23:59:59+00:00','units':units,'last_attempt':now,'research':{'method':'revenue-yoy-v1; package evidence-bound method verified by content digest; retained pilot horizons (0,3], (3,12], (12,60] months, not later one-quarter/1–3-year/5+-year convention or user holding preference','assumptions':['Local method authored 2026-11-16; no future economics used','Retained official filing date metadata accepted with fresh date verification pending'],'changes':'First managed Q3 checkpoint; no predecessor. Compared Q2 independently; retained drafts/history preserved. Growth and bounded fiscal identity completed only.','gaps':['investment-case required question pending','Original raw HTML/contextRef and filing-index/amendment coverage pending','Full narrative, notes, governance, competition, forecast, valuation and independently verified price pending'],'horizons':horizons}}
try:
 saved=m.publish(root,'aapl',review,files,expected,'run-01-q3',complete=False)
 (root/'run-01-publication.json').write_text(json.dumps(saved,indent=2));print(json.dumps(saved))
except (ValueError,OSError) as e:
 (root/'run-01-error.json').write_text(json.dumps({'run':'run-01-q3','error':str(e)}));raise
after=m.discover(root,'latest',review['cutoff']);(root/'run-01-discovery-after.json').write_text(json.dumps(after,indent=2));print(json.dumps(after,indent=2))
